const toRad = d => d * Math.PI / 180;

// Current device location (San Francisco)
const lat1 = 37.7749, lon1 = -122.4194;

// Boston, MA 02118 (approximate center of zip code)
const lat2 = 42.3396, lon2 = -71.0637;

// Haversine formula
const R_km = 6371;
const R_mi = 3958.8;

const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 +
          Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const km = (R_km * c).toFixed(1);
const mi = (R_mi * c).toFixed(1);

console.log('=== Distance Estimate ===');
console.log('From:  (37.7749, -122.4194) — San Francisco, CA');
console.log('To:    (42.3396, -71.0637)  — 4829 Elm Ridge Way, Suite 7, Boston, MA 02118');
console.log('');
console.log('Straight-line (great-circle) distance:');
console.log('  ' + Number(km).toLocaleString() + ' km');
console.log('  ' + Number(mi).toLocaleString() + ' miles');
"

