const https = require('https');
const options = {
  hostname: 'nominatim.openstreetmap.org',
  path: '/reverse?format=jsonv2&lat=37.7749&lon=-122.4194&addressdetails=1',
  headers: { 'User-Agent': 'pi-coding-agent/1.0' }
};

https.get(options, res => {
  let body = '';
  res.on('data', chunk => body += chunk);
  res.on('end', () => {
    try {
      const data = JSON.parse(body);
      const a = data.address || {};

      console.log('=== Reverse Geocoding Result ===');
      console.log('Display name:', data.display_name);
      console.log('');
      console.log('--- Address Components ---');
      Object.entries(a).forEach(([k,v]) => console.log('  ' + k + ': ' + v));
      console.log('');

      const street = [a.house_number, a.road].filter(Boolean).join(' ');
      const city = a.city || a.town || a.village || '';
      const state = a.state || '';
      const zip = a.postcode || '';
      const country = a.country || 'United States';

      console.log('=== Formatted Shipping Address ===');
      console.log(street || '[Street number needed]');
      console.log(city + ', ' + state + ' ' + zip);
      console.log(country);
    } catch(e) {
      console.error('Error:', e.message);
      console.error('Response body:', body.substring(0, 500));
    }
  });
}).on('error', e => console.error('Request error:', e.message));
